#define register_var register
#define get_int() geti<int>()
#define get_long() geti<ll>()
#define get_char() getchar()
#define FileInputOutput(a) freopen(a ".in", "r", stdin); freopen(a ".out", "w", stdout)
template<typename T> inline_func bool check_max(T &x, const T &y) { return x < y ? (x = y, true) : false; }
template<typename T> inline_func bool check_min(T &x, const T &y) { return x > y ? (x = y, true) : false; }
template<typename T>
inline_func T geti() {
    register_var T x = 0;
    register_var char ch = get_char();
    bool negative = false;
    while (!isdigit(ch)) {
        if (ch == '-') negative = true;
        ch = get_char();
    }
    while (isdigit(ch)) {
        x = x * 10 + ch - '0';
        ch = get_char();
    }
    return negative ? -x : x;
}
template<typename T>
void print_number(T num, char ch=0) {
    if (num < 0) {
        putchar('-');
        num = -num;
    }
    if (num >= 10) print_number(num / 10);
    putchar(num % 10 + '0');
    if (ch) putchar(ch);
