const int MAXN = 3e5 + 10;
int P;
int f[19][MAXN];
int inv_factorial[MAXN], factorial[MAXN], modular_inverse[MAXN];

ll fast_power(ll base, int exponent, ll modulus=1) {
    for (; exponent; exponent >>= 1, base = base * base % modulus)
        if (exponent & 1) modulus = modulus * base % modulus;
    return base;
}

void initialize(int n) {
    factorial[0] = 1;
    for (int i=1; i<=n; ++i) factorial[i] = 1LL * factorial[i-1] * i % P;
    inv_factorial[n] = fast_power(factorial[n], P-2);
    for (int i=n-1; i>=0; --i) inv_factorial[i] = 1LL * inv_factorial[i+1] * (i+1) % P;
    modular_inverse[1] = 1;
    for (int i=2; i<=n; ++i) modular_inverse[i] = 1LL * (P - P/i) * modular_inverse[P%i] % P;
}

void add_mod(int &x, int y) {
    x += y;
    if (x >= P) x -= P;
}

void subtract_mod(int &x, int y) {
    x -= y;
    x -= (x >> 31) * P;
}

void format_transform(int *f, int n) {
    for (int length=1; length<n; length <<= 1)
        for (int i=0; i<n; i+=length<<1)
            for (int j=0; j<length; ++j)
                add_mod(f[i+j+length], f[i+j]);
}

void inverse_format_transform(int *f, int n) {
    for (int length=1; length<n; length <<= 1)
        for (int i=0; i<n; i+=length<<1)
            for (int j=0; j<length; ++j)
                subtract_mod(f[i+j+length], f[i+j]);
}

int n, k;
#define count_bits(x) __builtin_popcount(x)
int low_primes[MAXN];

void compute_ln(int *f, int *g, int n) {
    g[0] = 0;
    for (int i=1; i<n; ++i) {
        g[i] = 0;
        for (int j=1; j<i; ++j)
            g[i] = (g[i] + 1LL * f[i-j] * g[j] % P * j) % P;
        g[i] = (f[i] + 1LL * g[i] * (P - modular_inverse[i])) % P;
    }
}

void compute_exp(int *f, int *g, int n) {
    g[0] = 1;
    for (int i=1; i<n; ++i) {
        g[i] = 0;
        for (int j=1; j<=i; ++j)
            g[i] = (g[i] + 1LL * g[i-j] * f[j] % P * j) % P;
        g[i] = (1LL * g[i] * modular_inverse[i]) % P;
    }
}

int main() {
