    int answer = fast_power(k, n, P);
    if (~n & 1) {
        int m = (int)log2(n) + 1;
        initialize(1 << m);
        for (int i=0; i<(1<<m); ++i) {
            f[count_bits(i)][i] = inv_factorial[i];
        }
        format_transform(f[0], 1<<m);
        static int F[20], G[20];
        for (int i=0; i<(1<<m); ++i) {
            for (int j=0; j<=m; ++j) {
                F[j] = f[j][i];
            }
            compute_ln(F, G, m+1);
            for (int j=0; j<=m; ++j) G[j] = 1LL * G[j] * k % P;
            compute_exp(G, F, m+1);
            for (int j=0; j<=m; ++j) {
                f[j][i] = F[j];
            }
        }
        inverse_format_transform(f[count_bits(n)], 1<<m);
        answer = (P + answer - 1LL * f[count_bits(n)][n] * factorial[n] % P) % P;
    }
    print_number(answer);
    return 0;
}
